    throw new Error('PERMANENTE: Gemini bloqueó el contenido del documento');
  }
  const candidate = response.candidates?.[0];
  const finish = candidate?.finishReason;
  if (['SAFETY', 'BLOCKLIST', 'PROHIBITED_CONTENT', 'SPII', 'RECITATION', 'LANGUAGE'].includes(finish)) {
    throw new Error('PERMANENTE: Gemini no aceptó interpretar este documento');
